const m=new Map();
exports.getStore=()=>({
  async get(k,o){ if(!m.has(k)) return null; const v=m.get(k); return (o&&o.type==='json')?JSON.parse(v):v; },
  async set(k,v){ m.set(k,String(v)); }, async setJSON(k,v){ m.set(k,JSON.stringify(v)); }, async delete(k){ m.delete(k); },
  async list(o){ const pre=(o&&o.prefix)||''; return { blobs:[...m.keys()].filter(k=>k.startsWith(pre)).map(key=>({key})), directories:[] }; },
  _m:m });
